/*
 * shit os 2 -- interrupt entry stubs.
 *
 * Every vector needs its own entry point, because the CPU does not tell the
 * handler which vector fired. Rather than write 256 near-identical functions,
 * the table below is generated by the assembler at a fixed 16-byte stride, so
 * the IDT can be filled with isr_stub_table + vector * 16.
 *
 * Each stub normalises the stack -- pushing a dummy error code for the vectors
 * that do not have one -- and falls into isr_common, which saves the rest of
 * the register state and calls into C++.
 */

#define STUB_STRIDE 16

/* Offset of the saved CS within the frame, once all registers are pushed. */
#define FRAME_CS_OFFSET 144

.section .text, "ax", @progbits
.code64

.align 16
.global isr_stub_table
.type isr_stub_table, @function
isr_stub_table:
vector = 0
.rept 256
    .align STUB_STRIDE
    /*
     * Vectors 8, 10-14, 17, 21, 29 and 30 push an error code themselves. For
     * every other vector we push a zero so that the frame layout is uniform.
     */
    .if (vector != 8) && (vector < 10 || vector > 14) && (vector != 17) && (vector != 21) && (vector != 29) && (vector != 30)
        pushq $0
    .endif
    pushq $vector
    jmp isr_common
    vector = vector + 1
.endr

.type isr_common, @function
isr_common:
    /* Order matters: this has to produce kernel::InterruptFrame exactly. */
    pushq %rax
    pushq %rbx
    pushq %rcx
    pushq %rdx
    pushq %rsi
    pushq %rdi
    pushq %rbp
    pushq %r8
    pushq %r9
    pushq %r10
    pushq %r11
    pushq %r12
    pushq %r13
    pushq %r14
    pushq %r15

    /*
     * If we came from ring 3, the GS base still belongs to userspace. Swap in
     * the kernel's per-CPU pointer before any C++ runs, and swap it back on
     * the way out.
     */
    testb $3, FRAME_CS_OFFSET(%rsp)
    jz 1f
    swapgs
1:
    /* The SysV ABI requires DF clear on entry to a C function. */
    cld

    movq %rsp, %rdi
    call interrupt_dispatch

    /*
     * The dispatcher returns the frame to resume, which is normally the one it
     * was given but is a different thread's frame when the scheduler decided
     * to preempt. Switching stacks here is what makes preemption work.
     */
    movq %rax, %rsp

    testb $3, FRAME_CS_OFFSET(%rsp)
    jz 2f
    swapgs
2:
    popq %r15
    popq %r14
    popq %r13
    popq %r12
    popq %r11
    popq %r10
    popq %r9
    popq %r8
    popq %rbp
    popq %rdi
    popq %rsi
    popq %rdx
    popq %rcx
    popq %rbx
    popq %rax

    /* Discard the vector and error code the stub pushed. */
    addq $16, %rsp
    iretq

.section .note.GNU-stack, "", @progbits
